import * as T from './vendor/three.module.js';
import {ghostModel} from './chapel-ghost.js';
import {chapelQuest,CHAPEL_OBJECTIVES} from './chapel-quest.js';
import {addItem,countItem,removeItem} from './inventory.js';
export const STORY_OBJECTIVES={...CHAPEL_OBJECTIVES,ritual_done:'Войдите в склеп и победите Лича',lich_relic:'Осмотрите останки Лича',lich_return:'Покажите печать склепа Джону',grave_search:'Осмотрите разграбленную могилу за склепом',grave_return:'Расскажите Джону о следах у могилы',chapter_complete:CHAPEL_OBJECTIVES.chapter_complete};
export const cryptUnlocked=p=>p.rewards.includes('ritual-purified');
export function chapterStory({p,slots,dungeon,cemetery,chapel,show,close,sync,sound,reward,scene,john,time=()=>0,bags=()=>[]}){
 let witness=null,witnessUntil=0;const owned=id=>countItem(slots,id)+bags().reduce((sum,b)=>sum+b.items.filter(i=>i.id===id).reduce((s,i)=>s+i.count,0),0);
 function dismiss(){if(witness)witness.visible=false;witnessUntil=0}
 function summon(){if(!scene||!john)return;if(!witness)witness=ghostModel(scene);witness.position.copy(john.g.position).add(new T.Vector3(1.3,.45,.6));witness.rotation.y=john.heading||0;witness.visible=true;witnessUntil=time()+8}
 const next=chapelQuest({p,slots,world:chapel,show,close,sync,sound,reward,owned,take:id=>removeItem(slots,id),summon,dismiss});
 function tick(){if(witnessUntil&&time()>=witnessUntil)dismiss();next.tick();if(p.stage==='ritual_done'&&dungeon?.boss?.hp===0){p.stage='lich_relic';sync();show('Лич повержен','Кости рассыпаются, и на камни падает свинцовая печать. На ней оттиснут колокол. Даже после гибели Лича где-то за кладбищем слышен звон.')}}
 function claim(){if(p.stage!=='lich_relic')return;if(!countItem(slots,'memory_medallion')&&!addItem(slots,'memory_medallion'))return show('Печать склепа','Освободите ячейку в сумке. Печать останется среди останков Лича.');p.stage='lich_return';reward(p,'lich-quest','quest',100);sync();sound();show('След звонаря','Вы забрали печать с клеймом часовни. Покажите её Джону: он знает старые захоронения и людей, которые здесь служили.')}
 function talk(){if(next.talk())return true;if(p.stage==='lich_return'){p.stage='grave_search';sync();sound();show('Джон','Знаю этот знак. Так запечатывали вещи служителей старой часовни. Их хоронили за склепом. У одной могилы недавно сдвинули плиту — я думал, что это дело Лича. Осмотри камень с зеленоватым свечением в конце дорожки.');return true}if(p.stage==='grave_return'){p.stage='chapter_complete';reward(p,'empty-grave','quest',40);sync();sound();show('Джон','Значит, могилу вскрывали руками, а не изнутри. Кто-то забрал останки служителя и унёс их к часовне. Ведьма гнала на нас зверей, Лич поднимал мёртвых… но звон не прекратился после их смерти. Нужно разобраться с самим колоколом. Поговори со мной, когда соберёшься в путь.');return true}if(Object.hasOwn(STORY_OBJECTIVES,p.stage)){show('Джон',p.stage==='grave_search'?'Светящийся камень за склепом. Посмотри, кто трогал могилу и что унесли.':p.stage==='lich_relic'?'Осмотри то, что осталось после Лича. Клеймо на его вещах может привести к часовне.':'Оберег пропустит тебя в склеп. Покончи с тем, кто поднимает наших мёртвых.');return true}return false}
 function grave(){if(p.stage!=='grave_search')return;p.stage='grave_return';sync();show('Разграбленная могила','На камне: «Служителю часовни». По краям плиты видны следы лома. В гробу пусто, на земле — обрывок верёвки с таким же узлом, каким связаны вещи слуг Лича. Следы волочения уходят к южной арке. Расскажите Джону.')}
 function guardTalk(){if(p.stage==='kingdom_letter'){show('Стражник Альфред','Джон уже рассказал мне о звонаре. Если эти люди готовят новую беду, нам нужна помощь. Я написал в королевство: о налётах, пропавших людях и перекрытых дорогах. Доставь письмо представителю королевской стражи. Пусть там узнают, что творится в Темнолесье.',[['Взять письмо',()=>{if(!countItem(slots,'alfred_letter')&&!addItem(slots,'alfred_letter'))return show('Альфред','Освободи ячейку для письма и возвращайся.');p.stage='kingdom_road';sync();sound();show('Письмо в королевство','Письмо Альфреда лежит в сумке. Деревня получила передышку, но теперь нужно добраться до королевства и попросить о помощи. Путешествие продолжится во второй главе.')}],['Мне нужно подготовиться',close]]);return true}if(p.stage==='kingdom_road'){if(owned('alfred_letter')===0){show('Альфред','Потерял письмо? Я сохранил черновик. Возьми новую копию и береги её.',[['Получить письмо',()=>{if(addItem(slots,'alfred_letter'))show('Альфред','Вот. Доставь его королевской страже.');else show('Альфред','В сумке нет свободного места.')}],['Позже',close]])}else show('Альфред','Письмо нужно передать королевской страже. А мы пока укрепим ворота и запасёмся едой.');return true}return false}
 return {tick,claim,talk,grave,prompt(){if(dungeon?.mode==='lich'&&p.stage==='lich_relic'&&dungeon.nearRemains?.())return 'E — Осмотреть останки Лича';if(cemetery?.nearStoryGrave?.()&&p.stage==='grave_search')return 'E — Осмотреть разграбленную могилу';return ''},guardTalk,chapelInteract:next.interact};
}
